import Mathlib

variable {N : ℕ}
abbrev Cell (N : ℕ) : Type := Fin (N + 2) × Fin (N + 1)
abbrev InteriorRow (N : ℕ) : Type := (Set.Icc 1 ⟨N, by omega⟩ : Set (Fin (N + 2)))
abbrev MonsterData (N : ℕ) : Type := InteriorRow N ↪ Fin (N + 1)
def MonsterData.monsterCells (m : MonsterData N) : Set (Cell N) :=
  Set.range (fun x : InteriorRow N ↦ ((x : Fin (N + 2)), m x))
def Adjacent (x y : Cell N) : Prop :=
  Nat.dist x.1 y.1 + Nat.dist x.2 y.2 = 1

import Mathlib

open Multiset

def BaseSkewT4 : Fin 4 → Multiset (ℕ × ℕ)
  | 1 => {(0, 0), (1, 0), (1, 1), (2, 1)}
  | 2 => {(1, 0), (1, 1), (0, 1), (0, 2)}
  | 3 => {(0, 1), (1, 1), (1, 0), (2, 0)}
  | 4 => {(0, 0), (0, 1), (1, 1), (1, 2)}

def SkewT4 (q : Fin 4 × ℕ × ℕ) : Multiset (ℕ × ℕ) :=
  (BaseSkewT4 q.1).map λ p ↦ q.2 + p

theorem imo_sl_2014_C4 {P Q : Multiset (Fin 4 × ℕ × ℕ)}
    (h : (map SkewT4 P).sum = (map SkewT4 Q).sum) (i : Fin 4) :
    (P.map Prod.fst).count i % 2 = (Q.map Prod.fst).count i % 2 := by
  have hcount : ∀ e : ℕ × ℕ, ((map SkewT4 P).sum).count e = ((map SkewT4 Q).sum).count e := by
    intro e; rw [h]
  fin_cases i <;> simp_all (config := { decide := true }) [BaseSkewT4, SkewT4, Fin.isValue,
    Multiset.count_map, Multiset.sum_map_add, Multiset.count_sum, Multiset.map_map,
    Function.comp, Multiset.count_add, Multiset.count_singleton] <;> omega

import Mathlib

def targetSumPair {F : Type*} [Field F] (r : F) (l : List F) : F × F :=
  l.foldr (λ a p ↦ (a / (r - a) * p.2 ^ 2 + p.1, a + p.2)) (0, 0)
